#include "typed-plant-row-parser.h"

std::optional<std::vector<charm::v1n7::kindergarten_garden::ChildPlants>> charm::v1n7::kindergarten_garden::parse_typed_garden(std::string_view top,std::string_view bottom,const std::vector<std::string>& children){if(top.size()!=bottom.size()||top.size()%2!=0||children.size()!=top.size()/2)return std::nullopt;std::set<std::string> names;auto decode=[](char c)->std::optional<PlantCode>{if(c=='C')return PlantCode::clover;if(c=='G')return PlantCode::grass;if(c=='R')return PlantCode::radish;if(c=='V')return PlantCode::violet;return std::nullopt;};std::vector<ChildPlants> out;for(std::size_t i=0;i<children.size();++i){if(children[i].empty()||!names.insert(children[i]).second)return std::nullopt;auto a=decode(top[2*i]),b=decode(top[2*i+1]),c=decode(bottom[2*i]),d=decode(bottom[2*i+1]);if(!a||!b||!c||!d)return std::nullopt;out.push_back({children[i],{*a,*b,*c,*d}});}return out;}
